#include <print>

int main() {
    int price = 8;
    int count = 3;

    int total = price * count;
    std::println("总价 = {}", total);
    std::println("付 100 找零 = {}", 100 - total);
    std::println("总价里有几个 10 = {}", total / 10);
    std::println("不满 10 的零头 = {}", total % 10);

    double money = 10.5;
    std::println("小数取余 = {}", money % 4);   // 报错里说 invalid operands

    return 0;
}

